CREATE TABLE [inv].[Item](
	[ItemId] [bigint] IDENTITY(100,5) NOT NULL,
	[Sku] [varchar](20) NOT NULL,
	[Price] [money] NOT NULL,
	[Weight] [float] NULL,
	[Qty] [int] NOT NULL,
	[Total]  AS ([Qty]*[Price]) PERSISTED,
	[Guid] [uniqueidentifier] NOT NULL DEFAULT (newsequentialid()),
	[Added] [datetimeoffset](7) NOT NULL,
	[Notes] [varchar](max) NULL,
	[Photo] [varbinary](max) NULL,
	[WarehouseId] [int] NOT NULL FOREIGN KEY REFERENCES [inv].[Warehouse]([WarehouseId]) ON DELETE CASCADE,
	[Kind] [nvarchar](10) NOT NULL,
 CONSTRAINT [PK_Item] PRIMARY KEY NONCLUSTERED ([ItemId]),
 CONSTRAINT [CK_Item_Kind] CHECK  (([Kind]='part' OR [Kind]='tool' OR [Kind]='kit'))
)
