CREATE PROCEDURE [inv].[Restock] @id int
AS
BEGIN
  UPDATE [inv].[Item] SET [Qty] = [Qty] + 1 WHERE [ItemId] = @id;
  IF @id > 0 BEGIN SELECT 1; END;
END
